function parseFlags(argv) {
  const flags = { _: [] };

  for (const arg of argv) {
    if (!arg.startsWith('--')) {
      flags._.push(arg);
      continue;
    }

    const body = arg.slice(2);
    const eq = body.indexOf('=');

    if (eq === -1) {
      flags[body] = true;
    } else {
      flags[body.slice(0, eq)] = body.slice(eq + 1);
    }
  }

  return flags;
}

module.exports = { parseFlags };

const test = require('node:test');
const assert = require('node:assert/strict');

const { parseFlags } = require('../src/flags');

test('empty argv yields only an empty positional list', () => {
  assert.deepEqual(parseFlags([]), { _: [] });
});

test('--name=value sets the name to the string value', () => {
  assert.deepEqual(parseFlags(['--out=x']), { _: [], out: 'x' });
});

test('--name without = sets the name to true', () => {
  assert.deepEqual(parseFlags(['--verbose']), { _: [], verbose: true });
});

test('arguments without a -- prefix are collected in order under _', () => {
  assert.deepEqual(parseFlags(['a', 'b']), { _: ['a', 'b'] });
});

test('flags and positionals can be mixed', () => {
  assert.deepEqual(parseFlags(['--verbose', '--out=x', 'a']), {
    _: ['a'],
    verbose: true,
    out: 'x',
  });
});
